public final class NonPokemonBatch114Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("swsh2_en_158");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static CardInstance hand(ServerMatch m,UUID p){return DynamicPassiveModifierTest.hand(m,p,"trainer");}
    static ServerMatch aiGame(String id){var c=new GeneratedRuleBatch28Test.Config();c.trainer=NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();c.attack=GeneratedRuleBatch8Test.hit(300,false);c.defenderAttack=c.attack;return GeneratedRuleBatch28Test.fixture(c);}
    static ServerMatch game(){return aiGame(IDS.getFirst());}
    static void choose(ServerMatch m,UUID p,int option){var q=m.effectChoicePrompt(p);m.chooseEffectOption(p,q.resolutionId(),q.step(),option);}
    public static void main(String[] args){outcomes();authorityAndPrivacy();shortDeck();existingPlayerChoices();ai();schema();System.out.println("NonPokemonBatch114Test passed: actual Dan draw-two then private RPS, both players/all gestures, repeated ties without extra draw, correct winner reward, empty/short decks, current chooser/step/session authority, sealed first gesture and public reveal only after second, concede cleanup, Tyme/Sordward actual final outcomes and four AI difficulties");}
    static void outcomes(){for(UUID p:List.of(A,B))for(int first=0;first<3;first++)for(int second=0;second<3;second++){
        var m=game();if(p.equals(B))m.endTurn(A);var source=hand(m,p);int before=m.privateView(p).hand().size(),opponent=m.privateView(other(p)).hand().size();m.playTrainer(p,source.instanceId(),null);check(m.privateView(p).hand().size()==before+1,"Dan initial draw did not precede RPS");
        var previous=m.effectChoicePrompt(p);choose(m,p,first);check(m.pendingChoicePlayer().equals(other(p)),"Second RPS player incorrect");choose(m,other(p),second);
        if(first==second){check(m.hasPendingEffectChoice()&&m.pendingChoicePlayer().equals(p)&&m.privateView(p).hand().size()==before+1,"Tie repeated draw or ended RPS");check(!m.effectChoicePrompt(p).resolutionId().equals(previous.resolutionId()),"Tie reused prompt authority");for(int i=0;i<3;i++){choose(m,p,i);choose(m,other(p),i);}choose(m,p,0);choose(m,other(p),2);}
        boolean win=first==second||Math.floorMod(first-second,3)==1;check(!m.hasPendingEffectChoice()&&m.privateView(p).hand().size()==before+1+(win?2:0)&&m.privateView(other(p)).hand().size()==opponent,"Dan rewarded wrong player or wrong draw count");check(m.privateView(p).discard().contains(source)&&!m.canPlayTrainer(p,hand(m,p).instanceId(),null),"RPS lost physical Supporter or usage");
    }}
    static void authorityAndPrivacy(){for(int first=0;first<3;first++){
        var m=game();m.playTrainer(A,hand(m,A).instanceId(),null);var q=m.effectChoicePrompt(A);var snapshot=m.clientView(A);var rng=m.randomTranscript();
        GeneratedRuleBatch8Test.reject(()->m.chooseEffectOption(B,q.resolutionId(),q.step(),0));GeneratedRuleBatch8Test.reject(()->m.chooseEffectOption(A,UUID.randomUUID(),q.step(),0));GeneratedRuleBatch8Test.reject(()->m.chooseEffectOption(A,q.resolutionId(),q.step()+1,0));GeneratedRuleBatch8Test.reject(()->m.chooseEffectOption(A,q.resolutionId(),q.step(),3));check(snapshot.equals(m.clientView(A))&&rng.equals(m.randomTranscript()),"Invalid gesture mutated match");
        int replay=m.replayTranscript().size();choose(m,A,first);check(m.replayTranscript().size()==replay+1&&m.replayTranscript().getLast().operation().equals("已秘密提交猜拳，等待对方"),"First gesture leaked into public replay");var second=m.effectChoicePrompt(B);check(second.optionsZh().equals(List.of("秘密出拳：石头","秘密出拳：布","秘密出拳：剪刀")),"Opponent labels leak first gesture");check(!m.canChooseEffectOption(A,0)&&m.canChooseEffectOption(B,0)&&!m.canChooseEffectOption(B,-1)&&!m.canChooseEffectOption(B,3),"RPS legal option bounds/owner incorrect");GeneratedRuleBatch8Test.reject(()->m.effectChoicePrompt(A));GeneratedRuleBatch8Test.reject(()->m.chooseEffectOption(A,q.resolutionId(),q.step(),0));GeneratedRuleBatch8Test.reject(()->m.chooseEffectOption(B,q.resolutionId(),q.step(),0));
        var session=MatchSession.multiplayer(m,A,B);check(session.view(B,B).options().stream().filter(o->o.type()==ActionType.CHOICE).count()==3&&session.view(A,A).options().stream().noneMatch(o->o.type()==ActionType.CHOICE),"Session exposed unsealed or wrong-owner RPS options");choose(m,B,(first+1)%3);check(m.replayTranscript().stream().anyMatch(e->e.operation().startsWith("猜拳揭晓：")),"Completed round not revealed");check(rng.equals(m.randomTranscript()),"Human RPS consumed game coin RNG");
    }var m=game();m.playTrainer(A,hand(m,A).instanceId(),null);choose(m,A,0);m.concede(B);check(m.phase()==MatchPhase.FINISHED&&!m.hasPendingEffectChoice(),"Concede stranded sealed RPS state");}
    static void shortDeck(){for(int size:List.of(0,1,2,3)){
        var m=game();var deck=PairedTrainerPlayTest.zone(m,A,"deck");var discard=PairedTrainerPlayTest.zone(m,A,"discard");while(deck.size()>size)discard.add(deck.removeFirst());var source=hand(m,A);int before=m.privateView(A).hand().size();if(size==0){check(!m.canPlayTrainer(A,source.instanceId(),null),"Empty-deck Dan had no possible draw effect");continue;}m.playTrainer(A,source.instanceId(),null);check(m.hasPendingEffectChoice(),"Dan skipped RPS after initial draw emptied deck");choose(m,A,0);choose(m,B,2);check(m.privateView(A).hand().size()==before-1+size&&!m.hasPendingEffectChoice(),"Short-deck RPS invented cards or stalled");
    }}
    static void ai(){for(var level:AiDifficulty.values())for(UUID p:List.of(A,B)){
        var m=game();if(p.equals(B))m.endTurn(A);m.playTrainer(p,hand(m,p).instanceId(),null);var session=MatchSession.multiplayer(m,A,B);AiCardOperationTest.settle(session,level);check(!m.hasPendingEffectChoice(),"AI RPS tie loop: "+level);AiCardOperationTest.finish(session,level);check(m.phase()==MatchPhase.FINISHED,"Dan AI match stalled: "+level);
    }}
    static void existingPlayerChoices(){for(UUID p:List.of(A,B))for(boolean correct:List.of(false,true)){
        var c=new GeneratedRuleBatch28Test.Config();c.trainer=NonPokemonBatch2Test.DATA.trainer("sv8-5_en_143").orElseThrow();c.ownHp=c.defenderHp=200;var m=GeneratedRuleBatch28Test.fixture(c);if(p.equals(B))m.endTurn(A);int own=m.privateView(p).hand().size(),opponent=m.privateView(other(p)).hand().size();m.playTrainer(p,hand(m,p).instanceId(),null);var q=m.effectCardPrompt(p);var card=q.candidates().stream().filter(x->x.definitionId().equals(p.equals(A)?"attacker":"defender")).findFirst().orElseThrow();m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(card.instanceId()));choose(m,other(p),correct?19:0);check(m.privateView(p).hand().size()==own-1+(correct?0:4)&&m.privateView(other(p)).hand().size()==opponent+(correct?4:0),"Tyme guessed but skipped actual reward");check(m.privateView(p).hand().contains(card),"Tyme removed chosen Pokemon");
    }for(UUID p:List.of(A,B))for(boolean allow:List.of(false,true)){
        var m=aiGame("swsh5_en_135");if(p.equals(B))m.endTurn(A);var recover=hand(m,p);m.discardHandCardsByEffect(p,p,List.of(recover.instanceId()));int before=m.privateView(p).hand().size();m.playTrainer(p,hand(m,p).instanceId(),null);var q=m.effectCardPrompt(p);m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(recover.instanceId()));choose(m,other(p),allow?0:1);check(m.privateView(p).hand().size()==before-1+(allow?1:3)&&m.privateView(p).hand().contains(recover)==allow,"Sordward decision skipped recovery/draw");
    }}
    static void schema(){var e=new EffectDefinition("rock_paper_scissors",EffectTarget.SELF,Map.of("winner_draw","2"),List.of(),List.of());for(var bad:List.of(new EffectDefinition(e.type(),EffectTarget.OPPONENT_ACTIVE,e.arguments(),List.of(),List.of()),new EffectDefinition(e.type(),e.target(),Map.of("winner_draw","3"),List.of(),List.of())))GeneratedRuleBatch8Test.reject(()->EffectSchemaValidator.validate(bad));GeneratedRuleBatch8Test.reject(()->ResumableProgramRules.validate(new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ONCE_PER_TURN,List.of(),List.of(e)))),true));}
}
